-- Venue categories (2026-10-22): the six venue types ("Barn / Rustic",
-- "Ballroom / Hotel", "Garden / Outdoor", "Beach / Waterfront",
-- "Historic / Estate", "Restaurant / Vineyard") become fifteen categories,
-- VENUE_TYPES in src/lib/wedding-options.ts. venues.venue_type and
-- weddings.venue_type stay plain text holding the label, so there is no
-- CHECK constraint to change, and public_venues (0091) selects the column
-- as-is and needs nothing either.
--
-- 1. Every venue that came from a batch file gets the category its batch row
--    now carries (sorted by src/lib/venue-category.ts). Rows match the way
--    the importer matches them, on source_id (the normalised website), and
--    failing that on name, city and state.
-- 2. Anything still on an old type (sample seed rows, rows added by hand)
--    gets a simple mapping from its old type and name.
-- 3. A couple's own venue-type preference maps to the nearest category.
--
-- Safe to re-run: every step only touches rows whose venue_type is not
-- already one of the fifteen, so a category chosen since is never undone.
-- 8598 batch rows.

create temp table if not exists venue_category_map (
  source_id text,
  name text not null,
  city text,
  state text,
  category text not null
);
truncate venue_category_map;


-- 1a. By source_id, as the importer keys rows.
update venues v
set venue_type = m.category
from (select distinct on (source_id) source_id, category from venue_category_map where source_id is not null order by source_id) m
where v.source_id = m.source_id
  and (v.venue_type is null or v.venue_type not in ('Barn & Farm', 'Ranch', 'Historic Mansion & Estate', 'Chapel & Church', 'Ballroom', 'Hotel & Resort', 'Garden & Park', 'Lake & River', 'Mountain & Lodge', 'Beach & Coast', 'Vineyard & Winery', 'Restaurant & Brewery', 'Country Club & Golf', 'Industrial Loft & Warehouse', 'Museum, Gallery & Rooftop'));

-- 1b. By name, city and state, for rows without a matching source_id.
update venues v
set venue_type = m.category
from (
  select distinct on (lower(name), coalesce(city, ''), coalesce(state, '')) name, city, state, category
  from venue_category_map
  order by lower(name), coalesce(city, ''), coalesce(state, '')
) m
where lower(v.name) = lower(m.name)
  and coalesce(v.city, '') = coalesce(m.city, '')
  and coalesce(v.state, '') = coalesce(m.state, '')
  and (v.venue_type is null or v.venue_type not in ('Barn & Farm', 'Ranch', 'Historic Mansion & Estate', 'Chapel & Church', 'Ballroom', 'Hotel & Resort', 'Garden & Park', 'Lake & River', 'Mountain & Lodge', 'Beach & Coast', 'Vineyard & Winery', 'Restaurant & Brewery', 'Country Club & Golf', 'Industrial Loft & Warehouse', 'Museum, Gallery & Rooftop'));

drop table venue_category_map;

-- 2. Whatever is still on an old type.
update venues
set venue_type = case
  when venue_type = 'Barn / Rustic' and name ~* '\m(ranch|rancho|hacienda)\M' then 'Ranch'
  when venue_type = 'Barn / Rustic' then 'Barn & Farm'
  when venue_type = 'Ballroom / Hotel' and name ~* '\m(golf|country club)\M' then 'Country Club & Golf'
  when venue_type = 'Ballroom / Hotel' and name ~* '\m(hotel|resort|inn|suites)\M' then 'Hotel & Resort'
  when venue_type = 'Ballroom / Hotel' then 'Ballroom'
  when venue_type = 'Garden / Outdoor' and name ~* '\m(lake|lakeside|river|riverside|creek|pond)\M' then 'Lake & River'
  when venue_type = 'Garden / Outdoor' and name ~* '\m(mountain|lodge|ridge|forest|woods|pines)\M' then 'Mountain & Lodge'
  when venue_type = 'Garden / Outdoor' then 'Garden & Park'
  when venue_type = 'Beach / Waterfront' and (state not in ('Alabama', 'Alaska', 'California', 'Connecticut', 'Delaware', 'Florida', 'Georgia', 'Hawaii', 'Louisiana', 'Maine', 'Maryland', 'Massachusetts', 'Mississippi', 'New Hampshire', 'New Jersey', 'New York', 'North Carolina', 'Oregon', 'Rhode Island', 'South Carolina', 'Texas', 'Virginia', 'Washington', 'District of Columbia') or name ~* '\m(lake|lakeside|lakefront|river|riverside|riverfront)\M') then 'Lake & River'
  when venue_type = 'Beach / Waterfront' then 'Beach & Coast'
  when venue_type = 'Historic / Estate' and name ~* '\m(chapel|church|cathedral)\M' then 'Chapel & Church'
  when venue_type = 'Historic / Estate' and name ~* '\m(museum|gallery|theatre|theater|library)\M' then 'Museum, Gallery & Rooftop'
  when venue_type = 'Historic / Estate' then 'Historic Mansion & Estate'
  when venue_type = 'Restaurant / Vineyard' and name ~* '\m(winery|vineyards?|wines?|cellars?)\M' then 'Vineyard & Winery'
  when venue_type = 'Restaurant / Vineyard' then 'Restaurant & Brewery'
end
where venue_type in ('Barn / Rustic', 'Ballroom / Hotel', 'Garden / Outdoor', 'Beach / Waterfront', 'Historic / Estate', 'Restaurant / Vineyard');

-- 3. Couples' own preference (set in /start and on the dashboard).
update weddings
set venue_type = case venue_type
  when 'Barn / Rustic' then 'Barn & Farm'
  when 'Ballroom / Hotel' then 'Ballroom'
  when 'Garden / Outdoor' then 'Garden & Park'
  when 'Beach / Waterfront' then 'Beach & Coast'
  when 'Historic / Estate' then 'Historic Mansion & Estate'
  when 'Restaurant / Vineyard' then 'Vineyard & Winery'
end
where venue_type in ('Barn / Rustic', 'Ballroom / Hotel', 'Garden / Outdoor', 'Beach / Waterfront', 'Historic / Estate', 'Restaurant / Vineyard');
